// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *BankAccount) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *BankAccount) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"no": {{"Bank_Account_Ledger_Entry", false, "bank_account_no", "", 0}, {"Bank_Account_Ledger_Entry", false, "bal_account_no", "bal_account_type", 3}, {"Check_Ledger_Entry", false, "bank_account_no", "", 0}, {"Check_Ledger_Entry", false, "bal_account_no", "bal_account_type", 3}, {"Comment_Line", false, "no", "table_name", 8}, {"Customer Ledger Entry", false, "bal_account_no", "bal_account_type", 3}, {"FA_Ledger_Entry", false, "bal_account_no", "bal_account_type", 3}, {"Gen_Journal_Batch", false, "bal_account_no", "bal_account_type", 3}, {"Gen_Journal_Line", false, "account_no", "account_type", 3}, {"Gen_Journal_Line", false, "bal_account_no", "bal_account_type", 3}, {"Gen_Journal_Line", false, "source_no", "source_type", 3}, {"Gen_Journal_Template", false, "bal_account_no", "bal_account_type", 3}, {"G_L_Entry", false, "bal_account_no", "bal_account_type", 3}, {"G_L_Entry", false, "source_no", "source_type", 3}, {"Maintenance_Ledger_Entry", false, "bal_account_no", "bal_account_type", 3}, {"Payment_Method", false, "bal_account_no", "bal_account_type", 1}, {"Vendor Ledger Entry", false, "bal_account_no", "bal_account_type", 3}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

// Delete removes the record from the database
func (t *BankAccount) Delete(runTrigger bool) bool {
	// OnDelete trigger of the business logic
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnDelete(); err != nil {
			fmt.Printf("Error: OnDelete trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, BankAccountTableName)

	// Collect arguments for DELETE
	args := []interface{}{
		t.No,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`DELETE FROM "%s" WHERE 1=1 AND no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	_, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to delete Bank_Account: %v\n", err)
		return false
	}
	return true
}

